import React from 'react';
import { CTag, Divider, Space } from '@cloud-materials/common';
import { COLORS, ARCO_COLORS, TYPES, LINEAR_COLORS } from '../constant';

const types = TYPES.slice(0, 3);
const typesWithoutText = TYPES.slice(0, 4);

export default () => {
  return (
    <Space direction="vertical">
      <Divider orientation="left">内置颜色</Divider>
      {typesWithoutText.map(type => (
        <Space key={type}>
          {COLORS.map(color => (
            <CTag key={`${type}-${color}`} color={color} type={type}>
              {color}
            </CTag>
          ))}
        </Space>
      ))}
      <Divider orientation="left">Arco 内置颜色</Divider>
      {typesWithoutText.map(type => (
        <Space key={type}>
          {ARCO_COLORS.map(color => (
            <CTag key={`${type}-${color}`} color={color} type={type}>
              {color}
            </CTag>
          ))}
        </Space>
      ))}
      <Divider orientation="left">内置渐变色</Divider>
      {['default', 'round', 'mark'].map(shape => (
        <Space key={shape}>
          {LINEAR_COLORS.map(color => (
            <CTag key={shape} shape={shape as any} color={color} type="default">
              {color}
            </CTag>
          ))}
        </Space>
      ))}

      <Divider orientation="left">自定义颜色</Divider>
      {typesWithoutText.map(type => (
        <Space key={type}>
          {['#f53f3f', '#7816ff', '#00b42a', '#165dff', '#ff7d00', '#eb0aa4', '#7bc616'].map(color => (
            <CTag key={`${type}-${color}`} color={color} type={type}>
              {color}
            </CTag>
          ))}
        </Space>
      ))}
      {typesWithoutText.map(type => (
        <Space key={type}>
          {[
            'tomato',
            'rgb(245, 63, 63)',
            'rgb(120, 22, 255)',
            'rgb(0, 180, 42)',
            'rgb(22, 93, 255)',
            'rgb(255, 125, 0)',
            'rgb(235, 10, 164)',
            'rgb(123, 198, 22)',
          ].map(color => (
            <CTag key={`${type}-${color}`} color={color} type={type}>
              {color}
            </CTag>
          ))}
        </Space>
      ))}
      <Divider orientation="left">异形标签颜色</Divider>
      <CTag shape="mark">mark</CTag>
      <Space direction="vertical">
        {types.map(type => (
          <Space key={type}>
            {COLORS.map(color => (
              <CTag key={`${type}-${color}`} color={color} type={type} shape="mark">
                {color}
              </CTag>
            ))}
          </Space>
        ))}
        {types.map(type => (
          <Space key={type}>
            {ARCO_COLORS.map(color => (
              <CTag key={`${type}-${color}`} color={color} type={type} shape="mark">
                {color}
              </CTag>
            ))}
          </Space>
        ))}
        {types.map(type => (
          <Space key={type}>
            {['#f53f3f', '#7816ff', '#00b42a', '#165dff', '#ff7d00', '#eb0aa4', '#7bc616'].map(color => (
              <CTag key={`${type}-${color}`} color={color} type={type} shape="mark">
                {color}
              </CTag>
            ))}
          </Space>
        ))}
      </Space>
    </Space>
  );
};

import React from 'react';
import { CTag, CTags, Divider, Space } from '@cloud-materials/common';
import { COLORS } from '../constant';

export default () => {
  return (
    <Space direction="vertical">
      <Divider orientation="left">标签组基本用法</Divider>
      <CTags data={Array.from({ length: 7 }).map((_, index) => `Tag ${index + 1}`)} />
      <CTags
        data={Array.from({ length: 3 }).map((_, index) => ({ prefix: `Prefix ${index}`, value: `Value ${index}` }))}
      />
      <Divider orientation="left">展开收起</Divider>
      <Space direction="vertical">
        <CTags maxShowCount={6} data={Array.from({ length: 7 }).map((_, index) => `Tag ${index + 1}`)} />
        <CTags maxShowCount={5} cCollapseProps={{ mode: 'popover' }}>
          {COLORS.map(color => (
            <CTag key={color} color={color} shape="round">
              {color}
            </CTag>
          ))}
        </CTags>
        <CTags maxShowCount={4} cCollapseProps={{ mode: 'popover' }}>
          {COLORS.map(color => (
            <CTag key={color} type="bordered" color={color}>
              {color}
            </CTag>
          ))}
        </CTags>
        <CTags maxShowCount={3} cCollapseProps={{ mode: 'popover' }}>
          {COLORS.map(color => (
            <CTag key={color} color={color} type="outline">
              {color}
            </CTag>
          ))}
        </CTags>
        <CTags maxShowCount={2} cCollapseProps={{ mode: 'popover' }}>
          {COLORS.map(color => (
            <CTag key={color} color={color} shape="mark">
              {color}
            </CTag>
          ))}
        </CTags>
        <CTags maxShowCount={1} cCollapseProps={{ mode: 'popover' }}>
          {COLORS.map(color => (
            <CTag key={color} type="text-dot" color={color}>
              {color}
            </CTag>
          ))}
        </CTags>
        <CTags maxShowCount={0}>
          {COLORS.map(color => (
            <CTag key={color} color={color}>
              {color}
            </CTag>
          ))}
        </CTags>
      </Space>
    </Space>
  );
};

import React from 'react';
import { CTag, CTags, Divider, Space } from '@cloud-materials/common';
import { COLORS } from '../constant';

export default () => {
  return (
    <Space direction="vertical">
      <Space direction="vertical">
        <Divider>开启复制</Divider>
        <CTags maxShowCount={3} copyable>
          {COLORS.map(color => (
            <CTag key={color} color={color}>
              {color}
            </CTag>
          ))}
        </CTags>
        <Divider>自定义分隔符</Divider>
        <CTags
          maxShowCount={3}
          copyable={{ separator: ',', buttonText: '自定义按钮', arcoButtonProps: { type: 'outline' } }}
        >
          {COLORS.map(color => (
            <CTag key={color} color={color}>
              <span>{color}</span>
            </CTag>
          ))}
        </CTags>
        <Divider>前缀标签组复制</Divider>
        <CTags
          maxShowCount={3}
          copyable
          data={Array.from({ length: 7 }).map((_, index) => ({ prefix: `${index}`, value: COLORS[index] }))}
        />
      </Space>
    </Space>
  );
};
